        Real const t71 =
            simdSelect(t70 == simdBroadcast<Real>(0), simdBroadcast<Real>(1.0 / 1.0), t70);
        Real const t72 = simdSqrt(t71);
        Real const t73 = simdBroadcast<Real>(1.0 / 1.0) / t72;
        Real const t74 = t70 * t73;
        Real const t75 = x * t73;
        Real const t76 =
            simdSelect(t70 == simdBroadcast<Real>(0), simdBroadcast<Real>(1.0 / 1.0), t75);
        Real const t77 = y * t73;
