        Real const t108 = t76 * t104;
        Real const t109 = simdFma((-t77), t102, t108);
        Real const t110 = source[1] * t77;
        Real const t112 = simdFma(source[3], t76, t110);
        Real const t113 = source[1] * t76;
        Real const t114 = simdFma(source[3], (-t77), t113);
        Real const t115 = source[5] * t77;
